572:         edge: reference,
573:         missing: [...requirement.required_claims].sort(compareStrings),
574:         disallowed: [],
575:       });
576:     }
577:     if (outcome.value.status === 'UNSATISFIED') {
578:       return validationValue({
579:         status: 'INVALID',
580:         code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
581:         edge: reference,
582:         missing: outcome.value.missing,
583:         disallowed: outcome.value.disallowed,
584:       });
585:     }
586:     return validationValue({
587:       status: 'CONTESTED',
588:       edge: reference,
589:       contestedClaims: outcome.value.contestedClaims,
590:     });
591:   }
592: 
593:   return validationValue({ status: 'VALID' });
594: }
595: 
596: function directParentBranches(graph: LineageGraph, child: IdentityVersionID): EdgeRef[] {
597:   const branches = new Map<string, EdgeRef>();
598:   for (const candidate of graph.edges) {
599:     if (candidate.child !== child) {
600:       continue;
601:     }
602:     const branch = edgeRef(candidate);
603:     branches.set(`${String(branch.parent)}\u0000${branch.relation}`, branch);
604:   }
605:   return [...branches.values()].sort(
606:     (a, b) => compareStrings(a.parent, b.parent) || compareStrings(a.relation, b.relation),
607:   );
608: }
609: 
610: function evaluateClosureBranch(
611:   branch: EdgeRef,
612:   assessments: readonly ContinuityAssessment[],
613:   requirement: ContinuityAssuranceRequirement,
614:   policy: Policy,
615:   ctx: TemporalContext,
616: ): Result<MergeClosureBranchFailure | undefined> {
617:   const outcome = evaluateEdgeAssurance(branch, assessments, requirement, policy, ctx);
618:   if (!outcome.ok) {
619:     return outcome;
620:   }
621: 
622:   if (outcome.value.status === 'SATISFIED') {
623:     return { ok: true, value: undefined };
624:   }
625:   if (outcome.value.status === 'NO_APPLICABLE_ASSESSMENT') {
626:     return { ok: true, value: { branch, reason: 'NO_APPLICABLE_ASSESSMENT' } };
627:   }
628:   if (outcome.value.status === 'UNSATISFIED') {
629:     return {
630:       ok: true,
631:       value: {
632:         branch,
633:         reason: 'ASSURANCE_UNSATISFIED',
634:         missing: outcome.value.missing,
635:         disallowed: outcome.value.disallowed,
636:       },
637:     };
638:   }
639:   return {
640:     ok: true,
641:     value: { branch, reason: 'CONTESTED', contestedClaims: outcome.value.contestedClaims },
642:   };
643: }
644: 
645: function closureBranchKey(branch: EdgeRef): string {
646:   return `${String(branch.child)}\u0000${String(branch.parent)}\u0000${branch.relation}`;
647: }
648: 
649: function collectBranchFailure(
650:   failures: Map<string, MergeClosureBranchFailure>,
651:   edge: EdgeRef,
652:   branch: EdgeRef,
653:   assessments: readonly ContinuityAssessment[],
654:   requirement: ContinuityAssuranceRequirement,
655:   policy: Policy,
656:   ctx: TemporalContext,
657: ): Result<undefined> {
658:   if (branch.parent === edge.parent && branch.relation === edge.relation) {
659:     return { ok: true, value: undefined };
660:   }
661:   const key = closureBranchKey(branch);
662:   if (failures.has(key)) {
663:     return { ok: true, value: undefined };
664:   }
665: 
666:   const failure = evaluateClosureBranch(branch, assessments, requirement, policy, ctx);
667:   if (!failure.ok) {
668:     return failure;
669:   }
670:   if (failure.value !== undefined) {
671:     failures.set(key, failure.value);
672:   }
673:   return { ok: true, value: undefined };
674: }
675: 
676: function collectEdgeClosureFailures(
677:   failures: Map<string, MergeClosureBranchFailure>,
678:   edge: EdgeRef,
679:   graph: LineageGraph,
680:   assessments: readonly ContinuityAssessment[],
681:   requirement: ContinuityAssuranceRequirement,
682:   policy: Policy,
683:   ctx: TemporalContext,
684: ): Result<undefined> {
685:   const branches = directParentBranches(graph, edge.child);
686:   if (!branches.some((branch) => branch.relation === 'MERGED_FROM')) {
687:     return { ok: true, value: undefined };
688:   }
689: 
690:   for (const branch of branches) {
691:     const collected = collectBranchFailure(failures, edge, branch, assessments, requirement, policy, ctx);
692:     if (!collected.ok) {
693:       return collected;
694:     }
695:   }
696:   return { ok: true, value: undefined };
697: }
698: 
699: function collectClosureFailures(
700:   path: Path,
701:   graph: LineageGraph,
702:   assessments: readonly ContinuityAssessment[],
703:   requirement: ContinuityAssuranceRequirement,
704:   policy: Policy,
705:   ctx: TemporalContext,
706: ): Result<Map<string, MergeClosureBranchFailure>> {
707:   const failures = new Map<string, MergeClosureBranchFailure>();
708: 
709:   for (const edge of path.edges) {
710:     const collected = collectEdgeClosureFailures(failures, edge, graph, assessments, requirement, policy, ctx);
711:     if (!collected.ok) {
712:       return collected;
713:     }
714:   }
715: 
716:   return { ok: true, value: failures };
717: }
718: 
719: function closureResult(failures: ReadonlyMap<string, MergeClosureBranchFailure>): MergeClosureResult {
720:   if (failures.size === 0) {
721:     return deepFreeze({ status: 'SATISFIED' }) as MergeClosureResult;
722:   }
723: 
724:   const orderedFailures = [...failures.values()].sort(
725:     (a, b) =>
726:       compareStrings(a.branch.child, b.branch.child) ||
727:       compareStrings(a.branch.parent, b.branch.parent) ||
728:       compareStrings(a.branch.relation, b.branch.relation),
729:   );
730:   return deepFreeze({
731:     status: 'UNSATISFIED',
732:     code: 'ERR_MERGE_BRANCH_UNSATISFIED',
733:     failures: orderedFailures,
734:   }) as MergeClosureResult;
735: }
736: 
737: /**
738:  * Phase 3: immediate merge closure. For every MERGED_FROM node on the path,
739:  * every direct parent edge of that node is checked, whatever its relation.
740:  * The exact edge already validated by Phase 2 is skipped; closure-only
741:  * branches are not recursed.
742:  */
743: export function validateMergeClosure(
744:   path: Path,
745:   graph: LineageGraph,
746:   assessments: readonly ContinuityAssessment[],
747:   requirement: ContinuityAssuranceRequirement,
748:   policy: Policy,
749:   ctx: TemporalContext,
750: ): Result<MergeClosureResult> {
751:   const shape = validatePathShape(path);
752:   if (!shape.ok) {
753:     return shape;
754:   }
755:   const membership = pathMembershipFailure(path, graph);
756:   if (!membership.ok) {
757:     return membership;
758:   }
759:   return validateMergeClosureAgainstGraph(path, graph, assessments, requirement, policy, ctx);
760: }
761: 
762: /** Closure over an already-checked path (evaluateBinding passes discovered paths). */
763: function validateMergeClosureAgainstGraph(
764:   path: Path,
765:   graph: LineageGraph,
766:   assessments: readonly ContinuityAssessment[],
767:   requirement: ContinuityAssuranceRequirement,
768:   policy: Policy,
769:   ctx: TemporalContext,
770: ): Result<MergeClosureResult> {
771:   const collected = collectClosureFailures(path, graph, assessments, requirement, policy, ctx);
772:   if (!collected.ok) {
773:     return collected;
774:   }
775:   return { ok: true, value: closureResult(collected.value) };
776: }
777: 
778: function asMechanism(failure: Failure): MechanismFailure {
779:   if (failure.kind === 'MECHANISM') {
780:     return failure;
781:   }
782:   return mechanismFailure('E_UNKNOWN_BOUNDARY_REJECTED', failure.message);
783: }
784: 
785: function mechanismResult(error: MechanismFailure): BindingResult {
786:   return deepFreeze({ eligible: false, kind: 'MECHANISM', error }) as BindingResult;
787: }
788: 
789: function mismatchResult(): BindingResult {
790:   return deepFreeze({ eligible: false, code: 'ERR_AUTHORITY_BINDING_MISMATCH', details: {} }) as BindingResult;
791: }
792: 
793: function evaluateOnePath(
794:   path: Path,
795:   graph: LineageGraph,
796:   cycleIndex: CycleIndex,
797:   assessments: readonly ContinuityAssessment[],
798:   requirement: ContinuityAssuranceRequirement,
799:   policy: Policy,
800:   ctx: TemporalContext,
801: ): Result<PathOutcome> {
802:   const validation = validatePathWithIndex(path, cycleIndex, assessments, requirement, policy, ctx);
803:   if (!validation.ok) {
804:     return validation;
805:   }
806:   if (validation.value.status !== 'VALID') {
807:     return { ok: true, value: { path, outcome: validation.value } };
808:   }
809: 
810:   const closure = validateMergeClosureAgainstGraph(path, graph, assessments, requirement, policy, ctx);
811:   if (!closure.ok) {
812:     return closure;
813:   }
814:   return { ok: true, value: { path, outcome: validation.value, closure: closure.value } };
815: }
816: 
817: /**
818:  * §8.3 prechecks: target participant, selector match and version label.
819:  */
820: function precheckCandidate(
821:   candidate: DeepReadonly<IdentityVersionDescriptor>,
822:   binding: ConditionalVersionBinding,
823: ): CandidatePrecheck {
824:   if (candidate.participant_id !== binding.target_participant_id) {
825:     return { ok: false, mismatch: true };
826:   }
827: 
828:   const compiled = compileSelector(binding.selector_expression, candidate.version_scheme);
829:   if (!compiled.ok) {
830:     return { ok: false, mismatch: false, error: asMechanism(compiled.error) };
831:   }
832:   const label = validateVersionLabel(candidate.version_label, candidate.version_scheme);
833:   if (!label.ok) {
834:     return { ok: false, mismatch: false, error: asMechanism(label.error) };
835:   }
836:   if (!selectorMatches(compiled.value, label.value)) {
837:     return { ok: false, mismatch: true };
838:   }
839: 
840:   return { ok: true };
841: }
842: 
843: function summarizePaths(accepted: readonly Path[], outcomes: readonly PathOutcome[]): BindingResult {
844:   if (accepted.length > 0) {
845:     return deepFreeze({
846:       eligible: true,
847:       acceptedPaths: accepted,
848:       details: { perPath: outcomes },
849:     }) as BindingResult;
850:   }
851: 
852:   // Task 10 aggregation order: closure failure outranks cycle and contested.
853:   if (outcomes.some((item) => item.closure?.status === 'UNSATISFIED')) {
854:     return deepFreeze({
855:       eligible: false,
856:       code: 'ERR_MERGE_BRANCH_UNSATISFIED',
857:       details: { perPath: outcomes },
858:     }) as BindingResult;
859:   }
860:   if (outcomes.some((item) => item.outcome.status === 'CYCLE_DETECTED')) {
861:     return deepFreeze({
862:       eligible: false,
863:       code: 'CYCLE_DETECTED',
864:       details: { perPath: outcomes },
865:     }) as BindingResult;
866:   }
867:   if (outcomes.some((item) => item.outcome.status === 'CONTESTED')) {
868:     return deepFreeze({
869:       eligible: false,
870:       kind: 'CONTESTED',
871:       details: { perPath: outcomes },
872:     }) as BindingResult;
873:   }
874:   return deepFreeze({
875:     eligible: false,
876:     code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED',
877:     details: { perPath: outcomes },
878:   }) as BindingResult;
879: }
880: 
881: /**
882:  * A duplicated descriptor id makes every lookup ambiguous: which record is the
883:  * candidate would depend on array order. The input is rejected instead.
884:  */
885: function duplicateDescriptorId(
886:   descriptors: readonly DeepReadonly<IdentityVersionDescriptor>[],
887: ): IdentityVersionID | undefined {
888:   const seen = new Set<IdentityVersionID>();
889:   for (const descriptor of descriptors) {
890:     if (seen.has(descriptor.id)) {
891:       return descriptor.id;
892:     }
893:     seen.add(descriptor.id);
894:   }
895:   return undefined;
896: }
897: 
898: /**
899:  * Orchestrates §8.3 prechecks, path discovery, per-path validation and
900:  * immediate merge closure, then aggregates the per-path outcomes.
901:  */
902: export function evaluateBinding(
903:   state: {
904:     graph: LineageGraph;
905:     descriptors: readonly DeepReadonly<IdentityVersionDescriptor>[];
906:     assessments: readonly ContinuityAssessment[];
907:   },
908:   binding: ConditionalVersionBinding,
909:   candidateID: IdentityVersionID,
910:   policy: Policy,
911:   ctx: TemporalContext,
912: ): BindingResult {
913:   const duplicateId = duplicateDescriptorId(state.descriptors);
914:   if (duplicateId !== undefined) {
915:     return mechanismResult(
916:       mechanismFailure('E_UNKNOWN_BOUNDARY_REJECTED', `Duplicate descriptor id in state.descriptors: ${duplicateId}`),
917:     );
918:   }
919:   const candidate = state.descriptors.find((descriptor) => descriptor.id === candidateID);
920:   if (candidate === undefined) {
921:     return mechanismResult(
922:       mechanismFailure('E_UNKNOWN_BOUNDARY_REJECTED', `Candidate descriptor ${candidateID} is not supplied`),
923:     );
924:   }
925: 
926:   const precheck = precheckCandidate(candidate, binding);
927:   if (!precheck.ok) {
928:     return precheck.mismatch ? mismatchResult() : mechanismResult(precheck.error);
929:   }
930: 
931:   const discovered = discoverPaths(state.graph, binding.traversal_scope, candidateID, binding.origin_version_id);
932:   if (!discovered.ok) {
933:     if (discovered.error.kind === 'MECHANISM') {
934:       return mechanismResult(discovered.error);
935:     }
936:     return deepFreeze({ eligible: false, code: 'ERR_NO_TRAVERSAL_PATH', details: {} }) as BindingResult;
937:   }
938: 
939:   const accepted: Path[] = [];
940:   const outcomes: PathOutcome[] = [];
941:   const cycleIndex = buildCycleIndex(state.graph);
942: 
943:   for (const path of discovered.value) {
944:     const evaluated = evaluateOnePath(
945:       path,
946:       state.graph,
947:       cycleIndex,
948:       state.assessments,
949:       binding.assurance_requirement,
950:       policy,
951:       ctx,
952:     );
953:     if (!evaluated.ok) {
954:       return mechanismResult(asMechanism(evaluated.error));
955:     }
956:     outcomes.push(evaluated.value);
957:     if (evaluated.value.outcome.status === 'VALID' && evaluated.value.closure?.status === 'SATISFIED') {
958:       accepted.push(path);
959:     }
960:   }
961: 
962:   return summarizePaths(accepted, outcomes);
963: }

