1: // Structural lineage validation for UIA-CORE-001 §5 (Task 6).
2: //
3: // Scope is deliberately limited to the structural rules of §5.2:
4: // per-relation cardinality, the CONTINUATION same-participant constraint, and
5: // self-parent rejection. Graph construction, delayed-parent resolution and
6: // cycle detection belong to Task 7 and live in a later part of this module.
7: //
8: // `validateDescriptor` is pure: it never mutates the descriptor or Registry,
9: // never inserts anything, and never normalizes or drops declared links.
10: 
11: import type { IdentityVersionDescriptor, LineageLink, LineageRelationType, ParticipantRecord } from './entities.js';
12: import { deepFreeze } from './ownership.js';
13: import type { DeepReadonly } from './ownership.js';
14: import type { IdentityVersionID } from './primitives.js';
15: 
16: /**
17:  * Read-only view of a domain's known participants and identity versions.
18:  *
19:  * Registry contents are assumed consistent: duplicate version ids are a caller
20:  * error and their behavior is unspecified, not a supported case.
21:  */
22: export interface Registry {
23:   participants(): readonly DeepReadonly<ParticipantRecord>[];
24:   versions(): readonly DeepReadonly<IdentityVersionDescriptor>[];
25: }
26: 
27: /** Result of the §5.2 structural rules. */
28: export type StructuralResult =
29:   | { readonly status: 'VALID' }
30:   | {
31:       readonly status: 'REJECTED';
32:       readonly code: 'ERR_INVALID_RELATION' | 'ERR_INVALID_CARDINALITY';
33:       readonly parent_version_id?: IdentityVersionID;
34:     };
35: 
36: interface CardinalityRule {
37:   readonly min: number;
38:   readonly max: number;
39: }
40: 
41: const CARDINALITY: Readonly<Record<LineageRelationType, CardinalityRule>> = {
42:   CONTINUATION: { min: 1, max: 1 },
43:   FORKED_FROM: { min: 1, max: 1 },
44:   MERGED_FROM: { min: 2, max: Number.POSITIVE_INFINITY },
45: };
46: 
47: const RELATIONS: readonly LineageRelationType[] = ['CONTINUATION', 'FORKED_FROM', 'MERGED_FROM'];
48: 
49: function findVersion(
50:   registry: Registry,
51:   versionId: IdentityVersionID,
52: ): DeepReadonly<IdentityVersionDescriptor> | undefined {
53:   return registry.versions().find((version) => version.id === versionId);
54: }
55: 
56: function findSelfParent(descriptor: DeepReadonly<IdentityVersionDescriptor>): IdentityVersionID | undefined {
57:   return descriptor.lineage.find((link) => link.parent_version_id === descriptor.id)?.parent_version_id;
58: }
59: 
60: /**
61:  * Effective count per relation. MERGED_FROM joins distinct parent lines, so
