892: 
893: **Responsibility:** §8 conditional version binding in three independently callable phases, plus orchestration. The phase contracts are in §3; this section lists the API.
894: 
895: ```ts
896: type LineageTraversalScope = 'CONTINUATION_ONLY' | 'CONTINUATION_AND_FORK' | 'FULL_ANCESTRY';
897: 
898: interface ConditionalVersionBinding {
899:   readonly target_participant_id: ParticipantID;
900:   readonly origin_version_id: IdentityVersionID;
901:   readonly selector_expression: string;
902:   readonly traversal_scope: LineageTraversalScope;
903:   readonly assurance_requirement: ContinuityAssuranceRequirement;
904: }
905: 
906: interface Path {
907:   readonly scope: LineageTraversalScope;
908:   readonly edges: readonly DeepReadonly<LineageEdge>[];
909: }
910: 
911: type PathSet = readonly Path[];
912: 
913: type PathValidation =
914:   | { readonly status: 'VALID' }
915:   | {
916:       readonly status: 'INVALID';
917:       readonly code: 'ERR_ASSURANCE_PREDICATE_UNSATISFIED';
918:       readonly edge: EdgeRef;
919:       readonly missing: readonly string[];
920:       readonly disallowed: readonly string[];
921:     }
922:   | { readonly status: 'CONTESTED'; readonly edge: EdgeRef; readonly contestedClaims: readonly string[] }
923:   | { readonly status: 'CYCLE_DETECTED'; readonly code: 'CYCLE_DETECTED'; readonly cycle: readonly IdentityVersionID[] };
924: 
925: type FailedPathValidation = Exclude<PathValidation, { readonly status: 'VALID' }>;
926: 
927: type MergeClosureBranchFailure =
928:   | { readonly branch: EdgeRef; readonly reason: 'NO_APPLICABLE_ASSESSMENT' }
929:   | {
930:       readonly branch: EdgeRef;
931:       readonly reason: 'ASSURANCE_UNSATISFIED';
932:       readonly missing: readonly string[];
933:       readonly disallowed: readonly string[];
934:     }
935:   | { readonly branch: EdgeRef; readonly reason: 'CONTESTED'; readonly contestedClaims: readonly string[] };
936: 
937: type MergeClosureResult =
938:   | { readonly status: 'SATISFIED' }
939:   | {
940:       readonly status: 'UNSATISFIED';
941:       readonly code: 'ERR_MERGE_BRANCH_UNSATISFIED';
942:       readonly failures: readonly MergeClosureBranchFailure[];
943:     };
944: 
945: interface PathOutcome {
946:   readonly path: Path;
947:   readonly outcome: PathValidation;
948:   readonly closure?: MergeClosureResult;
949: }
950: 
951: type FailedPath = PathOutcome & { readonly outcome: FailedPathValidation };
952: 
953: type BindingFailureCode =
954:   | 'ERR_AUTHORITY_BINDING_MISMATCH'
955:   | 'ERR_NO_TRAVERSAL_PATH'
956:   | 'ERR_ASSURANCE_PREDICATE_UNSATISFIED'
957:   | 'ERR_MERGE_BRANCH_UNSATISFIED'
958:   | 'CYCLE_DETECTED';
959: 
960: type BindingResult =
961:   | {
962:       readonly eligible: true;
963:       readonly acceptedPaths: readonly Path[];
964:       readonly details: { readonly perPath: readonly PathOutcome[] };
965:     }
966:   | { readonly eligible: false; readonly kind: 'MECHANISM'; readonly error: MechanismFailure }
967:   | { readonly eligible: false; readonly kind: 'CONTESTED'; readonly details: { readonly perPath: readonly PathOutcome[] } }
968:   | {
969:       readonly eligible: false;
970:       readonly code: BindingFailureCode;
971:       readonly details: { readonly perPath?: readonly PathOutcome[] };
972:     };
973: ```
