976: 
977: ```ts
978: function discoverPaths(
979:   graph: LineageGraph,
980:   scope: LineageTraversalScope,
981:   candidateID: IdentityVersionID,
982:   originID: IdentityVersionID,
983: ): Result<PathSet>;
