```
interface DiscoveryFrame { node; edges: readonly LineageEdge[]; next: number }
function collectPaths(...) {
  const paths: Path[] = [];
  const pathEdges: LineageEdge[] = [];
  const visited = new Set<IdentityVersionID>([candidateID]);
  const stack: DiscoveryFrame[] = [{ node: candidateID, edges: [], next: 0 }];

  while (stack.length > 0) {
    const frame = stack[stack.length - 1];
    if (frame.node === originID) {
      if (pathEdges.length > 0) paths.push(frozenPath(scope, pathEdges));
      stack.pop();
      if (stack.length > 0) {
        visited.delete(frame.node);
        pathEdges.pop();
      }
      continue;
