    if (frame.next >= edges.length) {
      stack.pop();
      if (stack.length > 0) {
        visited.delete(frame.node);
        pathEdges.pop();
      }
      continue;
    }
    const edge = edges[frame.next];
    frame.next += 1;
    if (visited.has(edge.parent)) continue;
    visited.add(edge.parent);
    pathEdges.push(edge);
    stack.push({ node: edge.parent, edges, next: 0 });
  }
  return paths;
}
```

