for i in 0..length: versions.push(descriptor({id:`iv-c${i}`, participant:'participant-a', lineage: i===0?[]:[link(`iv-c${i-1}`,'CONTINUATION')]}))
const graph = buildLineageGraph(registry([alice], versions));
